import { path, ts } from '@servicenow/sdk-build-core'
import { createTestContext, FluentXmlFluentTest, validateDiagnostic, xml, XmlFluentXmlTest } from '../test-utils'

const SCOPE = 'x_crossscope'

describe('Cross Scope Privilege plugin', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, 'project') })

    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    describe('Diagnostics', () => {
        test('hint diagnostic created when there is use of snake case in CrossScopePrivilege', async () => {
            const project = ctx.createProject({ config: { scope: SCOPE } })
            project.addFile({
                path: 'index.now.ts',
                content: `
                         import { CrossScopePrivilege } from '@servicenow/sdk/core'
    
    CrossScopePrivilege({
    $id: Now.ID['48c694e7c25a4a1481932a4517e31c73'],
    operation: 'execute',
    status: 'requested',
    target_name: 'target.name',
    targetScope: 'target.scope',
    targetType: 'scriptable',
})`,
            })
            const diagnostics = await project.getDiagnostics()
            expect(diagnostics).toHaveLength(1)
            validateDiagnostic(
                diagnostics,
                ts.SyntaxKind.StringLiteral,
                `The property 'target_name' is deprecated, use 'targetName' instead.`
            )
        })
    })

    describe('Fluent to XML', () => {
        test('generates XML with the correct fields', async () => {
            const project = ctx.createProject({ config: { scope: SCOPE } })
            const file = project.addFile({
                path: 'crossscope.now.ts',
                content: `import { CrossScopePrivilege } from '@servicenow/sdk/core'

CrossScopePrivilege({
    $id: Now.ID['pref-id'],
    operation: 'execute',
    status: 'requested',
    targetName: 'target.name',
    targetScope: 'target.scope',
    targetType: 'scriptable'
})
`,
            })

            const id = project.registerExplicitId('sys_scope_privilege', 'pref-id')

            expect(await project.getDiagnostics()).toHaveLength(0)
            const output = await file.getOutput()
            expect(output).toHaveLength(1)

            expect(output[0].content).toEqual(xml`<?xml version="1.0"?>
<record_update table="sys_scope_privilege">
  <sys_scope_privilege action="INSERT_OR_UPDATE">
    <sys_id>${id}</sys_id>
    <sys_scope display_value="${SCOPE}">11111111111111111111111111111111</sys_scope>
    <sys_update_name>sys_scope_privilege_${id}</sys_update_name>
    <operation>execute</operation>
    <source_scope>11111111111111111111111111111111</source_scope>
    <status>requested</status>
    <target_name>target.name</target_name>
    <target_scope>target.scope</target_scope>
    <target_type>scriptable</target_type>
  </sys_scope_privilege>
</record_update>`)
        })
    })

    describe('XML to Fluent', () => {
        test('basic XML', async () => {
            const project = ctx.createProject({ rootDir: __dirname })
            const output = await project.transform('./xml/sys_scope_privilege_48c694e7c25a4a1481932a4517e31c73.xml')

            expect(output.changedFiles).toHaveLength(1)
            expect(output.changedFiles[0].getContent()).toMatchInlineSnapshot(`
"import { CrossScopePrivilege } from '@servicenow/sdk/core'

CrossScopePrivilege({
    $id: Now.ID['48c694e7c25a4a1481932a4517e31c73'],
    operation: 'execute',
    status: 'requested',
    targetName: 'target.name',
    targetScope: 'target.scope',
    targetType: 'scriptable',
})
"
`)
        })
    })

    describe('Fluent => XML => Fluent', () => {
        test('files round-trips correctly', async () => {
            const project = ctx.createProject({ config: { scope: SCOPE } })
            const roundTripTest = new FluentXmlFluentTest(project)

            const id = roundTripTest.addId('sys_scope_privilege', 'pref-id')
            roundTripTest.addExpectedXmlFileNames(`sys_scope_privilege_${id}.xml`)

            roundTripTest.addFluentFragment(
                `
import { CrossScopePrivilege } from '@servicenow/sdk/core'

CrossScopePrivilege({
    $id: Now.ID['pref-id'],
    operation: 'execute',
    status: 'requested',
    targetName: 'target.name',
    targetScope: 'target.scope',
    targetType: 'scriptable'
})
`
            )

            await roundTripTest.verify()
        })

        // FIXME: Skipped because I don't think round-tripping the outputs as inputs should produce any changes, and this test started failing
        //  when I fixed the issue where we'd still try to commit a bunch of shapes derived from unchanged records.
        test.skip('CrossScopePrivilege with snake_case gets updated to camelCase on round-trip', async () => {
            const project = ctx.createProject({ rootDir: __dirname })
            project.registerExplicitId('sys_scope_privilege', 'pref-id')

            const cspFile = project.addFile({
                path: 'csp.now.ts',
                content: `import { CrossScopePrivilege } from '@servicenow/sdk/core'

CrossScopePrivilege({
    $id: Now.ID['pref-id'],
    operation: 'execute',
    status: 'requested',
    target_name: 'target.name',
    target_scope: 'target.scope',
    target_type: 'scriptable'
})
`,
            })

            const xmlOutputs = await cspFile.getOutput()
            const { changedFiles } = await project.transform(xmlOutputs)
            expect(await project.getDiagnostics()).toHaveLength(0)
            expect(changedFiles).toHaveLength(1)
            expect(changedFiles[0].getName()).toBe('csp.now.ts')
            expect(changedFiles[0].getContent()).toBe(`import { CrossScopePrivilege } from '@servicenow/sdk/core'

CrossScopePrivilege({
    $id: Now.ID['pref-id'],
    operation: 'execute',
    status: 'requested',
    targetName: 'target.name',
    targetScope: 'target.scope',
    targetType: 'scriptable',
})
`)
        })
    })

    describe('XML => Fluent => XML', () => {
        test('ACL with roles round-trips correctly', async () => {
            const project = ctx.createProject({
                rootDir: __dirname,
                config: { scope: SCOPE },
            })
            const originalFiles = ['./xml/sys_scope_privilege_48c694e7c25a4a1481932a4517e31c73.xml']
            const roundTripTest = new XmlFluentXmlTest(project, __dirname, originalFiles)
            await roundTripTest.verify()
        })
    })
})
